<template><main class="auth-page"><router-link class="brand" to="/"><span>Y</span><strong>Yu Like</strong></router-link><section class="auth-card section-card"><div class="intro"><span>JOIN THE COMMUNITY</span><h1>创建账号</h1><p>加入社区，开始分享内容并使用知识库助手。</p></div><form @submit.prevent="submit"><label class="form-field">用户名<input v-model.trim="form.username" class="input-control" minlength="2" autocomplete="username" required placeholder="至少 2 个字符"/></label><label class="form-field">邮箱<input v-model.trim="form.email" class="input-control" type="email" autocomplete="email" required placeholder="name@example.com"/></label><label class="form-field">密码<div class="password"><input v-model="form.password" class="input-control" :type="showPassword?'text':'password'" minlength="2" autocomplete="new-password" required placeholder="设置登录密码"/><button type="button" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></div></label><ErrorAlert :message="userStore.error"/><div v-if="success" class="form-success">{{success}}</div><button class="btn btn-primary submit" :disabled="userStore.loading">{{userStore.loading?'正在注册…':'创建账号'}}</button></form><footer>已有账号？<router-link to="/login">返回登录</router-link></footer></section></main></template>
<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import ErrorAlert from '../components/common/ErrorAlert.vue';import { useUserStore } from '../stores/user';
const router=useRouter(),userStore=useUserStore(),showPassword=ref(false),success=ref('');const form=reactive({username:'',email:'',password:''});async function submit(){const ok=await userStore.register(form);if(ok){success.value='注册成功，即将前往登录页。';setTimeout(()=>router.push('/login'),700);}}
</script>
<style scoped>.auth-page{display:grid;min-height:100vh;place-items:center;align-content:center;gap:22px;padding:24px;background:#f7f8fb}.brand{display:flex;align-items:center;gap:9px}.brand span{display:grid;width:36px;height:36px;place-items:center;border-radius:10px;background:#0f766e;color:white;font-weight:950}.auth-card{width:min(440px,100%);padding:32px}.intro span{color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.12em}.intro h1{margin:6px 0;font-size:30px}.intro p{margin:0 0 24px;color:#64748b;line-height:1.6}form{display:grid;gap:16px}.password{position:relative}.password input{padding-right:62px}.password button{position:absolute;top:50%;right:10px;border:0;background:none;transform:translateY(-50%);color:#0f766e;font-size:12px;font-weight:800}.submit{width:100%}.auth-card footer{border-top:1px solid #f1f5f9;margin-top:24px;padding-top:20px;color:#64748b;text-align:center;font-size:13px}.auth-card footer a{color:#0f766e;font-weight:850}</style>
